functions.spendMs:
{
      if(isNaN(val))
      {
         return undefined;
      }
      if(this.xxx_ms >= val)
      {
         this.xxx_ms -= val;
         return true;
      }
      return false;
   }

functions.exploitUp:
{
      val = Math.round(val);
      if(this.exploit >= 38500)
      {
         _global.sysMsg.addMsg("爵位已经达到最高，无法获得功勋了");
         return false;
      }
      this.exploit += val;
      var _loc4_ = this.exploit;
      var _loc3_ = 0;
      if(_loc4_ >= 38500)
      {
         _loc3_ = this.chaw < 5 ? (this.xxx_chaw = 5) : 0;
         this.exploit = 38500;
      }
      else if(_loc4_ >= 18500)
      {
         _loc3_ = this.chaw < 4 ? (this.xxx_chaw = 4) : 0;
      }
      else if(_loc4_ >= 8500)
      {
         _loc3_ = this.chaw < 3 ? (this.xxx_chaw = 3) : 0;
      }
